<script setup lang="ts">import { onMounted } from 'vue'; import { useTaskStore } from '../stores/tasks'; import StatusBadge from '../components/StatusBadge.vue'; const store=useTaskStore(); onMounted(()=>{void store.loadTasks().catch(()=>undefined)})</script>
<template><section class="page-stack"><header class="page-header"><div><p class="eyebrow">测试报告审核</p><h1>审核任务</h1></div><RouterLink class="btn btn-primary" to="/tasks/new">创建任务</RouterLink></header><article class="panel"><div class="table-wrap"><table><thead><tr><th>报告名称</th><th>审核模板</th><th>校验项</th><th>状态</th><th>创建时间</th></tr></thead><tbody><tr v-for="task in store.tasks" :key="task.id"><td><RouterLink :to="`/tasks/${task.id}`">{{ task.display_name }}</RouterLink></td><td>{{ task.template_name }} · {{ task.template_version }}</td><td>{{ task.template_rule_count }}</td><td><StatusBadge :status="task.state" /></td><td>{{ new Date(task.created_at).toLocaleString('zh-CN') }}</td></tr></tbody></table></div></article></section></template>
